unknown = set(requested) - {case["id"] for case in cases}
if unknown:
    parser.error("Unknown case ID(s): " + ", ".join(sorted(unknown)))
if requested:
    # Preserve original suite order, include each requested case once
    seen = set()
    selected = []
    for case in cases:
        if case["id"] in requested and case["id"] not in seen:
            selected.append(case)
            seen.add(case["id"])
else:
    selected = cases

